// Self-check for src/map/cities.ts (generated by scripts/build-cities.ts). Run: node --experimental-strip-types scripts/check-cities.ts
import { CITIES } from '../src/map/cities.ts';
import US from './us-region.json' with { type: 'json' };

const fail = (msg: string): never => {
  throw new Error(`check-cities: ${msg}`);
};
// The same boxes the US basemap is cut to: every city must land on the map.
const boxes = US.coordinates.map(([ring]) => [ring![0]!, ring![2]!] as const);
const inUS = (lon: number, lat: number) => boxes.some(([[w, s], [e, n]]) => lon >= w! && lon <= e! && lat >= s! && lat <= n!);

if (CITIES.length < 20) fail(`only ${CITIES.length} cities`);
const codes = new Set<string>();
for (const c of CITIES) {
  if (!/^[A-Z0-9]{3}$/.test(c.code)) fail(`bad code ${c.code}`);
  if (codes.has(c.code)) fail(`duplicate ${c.code}`);
  codes.add(c.code);
  if (!/^[A-Z]{2}$/.test(c.state) || !c.name) fail(`${c.code}: name/state`);
  if (!inUS(c.lon, c.lat)) fail(`${c.code} ${c.name} at ${c.lon},${c.lat} is outside the US basemap`);
}
for (const must of ['SEA', 'MCO']) if (!codes.has(must)) fail(`${must} missing`);
console.log(`check-cities: ok (${CITIES.length} cities)`);
